tree=ast.parse(s);v={n.targets[0].id:ast.literal_eval(n.value) for n in tree.body if isinstance(n,ast.Assign)}
pins=v['PINNED_BY_HOST'];pins['host-v36']={n:hashlib.sha256(x.encode()).hexdigest() for n,x in v['PAYLOAD'].items()}
for p in HOST.iterdir():
 if not p.is_file():continue
 x=p.read_text()
 if p.suffix=='.py':x=x.replace('1.3.8','1.4.0')
 if p.name=='phone_service.py':
  x=x.replace("VERSION = 'phone-service-36'","VERSION = 'phone-service-37'").replace("MARKER = '# OKX phone service v36 managed boot hook'","MARKER = '# OKX phone service v37 managed boot hook'")
  if "LEGACY_MARKERS = ('# OKX phone service v36 managed boot hook'" not in x:x=x.replace('LEGACY_MARKERS = (',"LEGACY_MARKERS = ('# OKX phone service v36 managed boot hook', ")
 if p.name=='phone_update.py':x=x.replace('CURRENT = 36','CURRENT = 37')
 if p.name=='phone_button_upgrade.py':x=x.replace("'host-v35')","'host-v35', 'host-v36')")
 p.write_text(x)
(HOST/'phone_button_old_sources.json').write_text(json.dumps(pins,ensure_ascii=False,indent=2)+'\n')
payload={p.name:p.read_text() for p in sorted(HOST.iterdir()) if p.is_file()}
assert payload['phone_sources.json']==v['PAYLOAD']['phone_sources.json']
lines=s.splitlines(keepends=True)
for n in reversed(tree.body):
 if isinstance(n,ast.Assign):
  k=n.targets[0].id
  if k in v:lines[n.lineno-1:n.end_lineno]=[k+' = '+repr({'PINNED_BY_HOST':pins,'HOST_NEW':'host-v37','PAYLOAD':payload}[k])+'\n']
out=''.join(lines);tree=ast.parse(out);n=next(n for n in tree.body if isinstance(n,ast.Assign) and n.targets[0].id=='PAYLOAD');lines=out.splitlines(keepends=True)
tail=''.join(lines[n.end_lineno:]).replace('host-v36','host-v37').replace('1.3.8','1.4.0').replace("for host in ('host-v35'","for host in ('host-v36','host-v35'")
out=''.join(lines[:n.end_lineno])+tail
out=out.replace('Verified phone host-v36: trend entry ends at KST02.','Verified phone host-v37: mobile computation, candidate and quote coordination.')
(D/'phone_1_4_0_setup.py').write_text(out)
meta=dict(bytes=len(out.encode()),chars=len(out),sha256=hashlib.sha256(out.encode()).hexdigest(),host='host-v37',version='1.4.0',files={n:hashlib.sha256(x.encode()).hexdigest() for n,x in payload.items()})
(Path(__file__).parent/'release.json').write_text(json.dumps(meta,ensure_ascii=False,indent=2)+'\n');print(json.dumps({k:v for k,v in meta.items() if k!='files'}))

