"""Reused Binance OHLCV: behavior regression, not a profit backtest or phone timing test."""
import bisect,copy,hashlib,json,pickle,sys
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2];WORK=ROOT.parent;HOST=ROOT/'android/phone_v140';CORE=WORK/'core121'
sys.path[:0]=[str(HOST),str(CORE)]

def main():
 import okx_channel701 as ch
 from phone_performance import Timing
 from phone_signal_cache import install
 from phone_parallel import Pool
 from okx_core import BotError
 data={};hashes={};alltimes=set()
 for symbol in ['ARB','OP','SEI','WLD','TIA']:
  p=WORK/'research_combo_20261115/reference/base/inputs'/(symbol+'.pickle')
  raw=p.read_bytes();hashes[p.name]=hashlib.sha256(raw).hexdigest();d=pickle.loads(raw);data[symbol]=d
  for frame in ('b','h','q'):
   for bar in d[frame]:bar[0]=int(bar[0])
  for v in d['proofs']['mild726'].values():alltimes.add(int(v['confirmation_ms']))
 b=data['OP']['b'];alltimes.update(b[1200+i*(len(b)-1201)//99][0] for i in range(100))
 cfg={'indicators':{'bb_period':20,'bb_multiplier':2,'ma_periods':[15,20,50,100,120,200]}}
 batches=[];positive=0
 for t in sorted(alltimes):
  now=t+900000;cases=[]
  for symbol,d in data.items():
   frames={}
   for k,f,step in [('b','15m',900000),('h','1H',3600000),('q','4H',14400000)]:
    bars=d[k];end=bisect.bisect_right([r[0]+step for r in bars],now);frames[f]=bars[max(0,end-300):end]
   row=dict(symbol=symbol+'-USDT-SWAP',instrument={'lever':'100','instCategory':'1'},live_frames=frames)
   expected=ch.packet(row,cfg,now);positive+=bool(expected['entry_setups'])
   cases.append((row,expected))
  batches.append((now,cases))
 timer=Timing('/tmp');timer.local.group='optimized';pins=json.loads((HOST/'phone_sources.json').read_text());cache=install(timer,pins)
 count=0
 def equal(got,want):
  if want['entry_setups']:
   got=dict(got);got.pop('entry_diagnostic',None);assert got==want
  else:assert got['entry_setups']==want['entry_setups'] and got['or_status']==want['or_status']
 for now,cases in batches:
  for row,expected in cases:
   with cache.packet_scope(row['symbol']):got=ch._phone_worker_packet(row,cfg,now)
   equal(got,expected);count+=1
 pool=Pool(str(CORE),pins);parallel=0
 try:
  chosen=batches # Every original/serial comparison also crosses actual spawn+IPC.
  for i,(now,cases) in enumerate(chosen,1):
   groups=[cases[j::4] for j in range(4)]
   tasks=[(i,now,cfg,[r['symbol'] for r,x in group],[r for r,x in group]) for group in groups]
   replies=pool.run(tasks)
   for group,(revision,packets) in zip(groups,replies):
    assert revision==i
    for row,expected in group:
     good,got=packets[row['symbol']];assert good;equal(got,expected);parallel+=1
 finally:pool.close()
 result={'scope':'reused Binance 2026 OHLCV, pure original PC core / phone serial / four spawned workers; not live PC configuration, live fills, profitability or Fold latency', 'symbols':list(data),'cutoffs':len(batches),'positive_packets':positive,'negative_packets':count-positive,'serial_comparisons':count,'parallel_comparisons':parallel,'mismatches':0,'input_sha256':hashes,'core_pins':pins}
 (Path(__file__).parent/'replay_results.json').write_text(json.dumps(result,ensure_ascii=False,indent=2)+'\n')
 print(json.dumps({k:v for k,v in result.items() if k not in ('input_sha256','core_pins')},ensure_ascii=False))
if __name__=='__main__':main()
